def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    op_c = 0
    my_c = 0
    for h in history:
        if h[1] == 'C':
            op_c += 1
        if h[0] == 'C':
            my_c += 1

    if n >= 10:
        rate = op_c / n
        if 0.3 <= rate <= 0.7 and my_c < n:
            if rng.random() < 0.8:
                return 'D'

    if op_c >= n - max(1, n // 10):
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    if op_c <= n // 2:
        return 'D'

    last_me, last_op = history[-1]
    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        return 'C'
